"""Environment-variable expansion for configuration values.

Spec (this docstring is the agreed contract)
--------------------------------------------
``expand(value, env) -> value``

- Strings: every ``${NAME}`` is replaced by ``env["NAME"]``;
  ``${NAME:default}`` uses the default when NAME is not in env. The
  default is everything after the FIRST colon, so it may itself
  contain colons (``${HOST:http://localhost:8080}``).
- A ``${NAME}`` reference with no default for a NAME missing from env
  raises ``KeyError``.
- ``$$`` is an escape producing one literal ``$`` and never starts a
  reference (``"$${X}"`` -> ``"${X}"``).
- Variable names consist of letters, digits and underscores.
- Dicts and lists are expanded recursively (keys are not expanded,
  values are). Non-string scalars pass through unchanged.
- The input is never mutated; containers are returned as new objects.
"""

import re

_PATTERN = re.compile(r"\$\{([A-Za-z0-9_]+)(:([^}]*))?\}")


def expand(value, env):
    if isinstance(value, str):
        def repl(match):
            name = match.group(1)
            if name in env:
                return env[name]
            if match.group(2) is not None:
                return match.group(3)
            raise KeyError(name)
        return _PATTERN.sub(repl, value)
    if isinstance(value, dict):
        return {k: expand(v, env) for k, v in value.items()}
    return value

"""Visible tests. These encode part of the spec in the module docstrings
and must not be weakened — the full spec is also exercised elsewhere."""

from expand import expand
from loader import load_layers
from merge import deep_merge


def test_merge_recurses_into_dicts():
    base = {"db": {"host": "a", "port": 1}, "x": 1}
    over = {"db": {"host": "b"}}
    assert deep_merge(base, over) == {"db": {"host": "b", "port": 1}, "x": 1}


def test_merge_none_deletes_key():
    assert deep_merge({"a": 1, "b": 2}, {"b": None}) == {"a": 1}


def test_merge_does_not_mutate_inputs():
    base = {"db": {"host": "a"}}
    over = {"db": {"host": "b"}}
    deep_merge(base, over)
    assert base == {"db": {"host": "a"}}


def test_expand_basic_and_default():
    assert expand("${HOST}", {"HOST": "h"}) == "h"
    assert expand("${HOST:fallback}", {}) == "fallback"


def test_loader_later_layers_win():
    cfg = load_layers([{"a": 1}, {"a": 2}], {})
    assert cfg == {"a": 2}

